#define PI     3.14159265
const float FOCAL_LENGTH = 1.2;
const int MAX_RAY_STEPS = 1000;
const int MAX_SHADOW_STEPS = 50;
const int MAX_REFLECTIONS = 10;
const float MIN_RAY_DIST = 0.0001;
const float MAX_RAY_DIST = 100.;
const float RAY_PRECISION = 0.00001;
const float NORMAL_PRECISION = 0.0001;
const float SHADOW_DARKNESS = 0.01;
const float SHADOW_HARDNESS = 50.0;

const float SATURATION = 2.0;
const float GAMMA = 1.75;


vec3 move(vec3 point, vec3 delta){
    return point - delta;
}
mat2 rotation(float angle){
    float s=sin(angle), c=cos(angle);
    return mat2(c, -s, s, c);
}

float wave(vec3 p){
    float k = 0.0;
    k -= 0.15*sin((p.x)*3. + iTime/10.*7.);
    k -= 0.05*cos(p.z/2. + iTime/10.*11.);
    k -= 0.05*sin(p.z*3. + iTime/10.*13.);
    k += -0.5*(sin(p.x-(iTime))*sin(p.x-(2.*iTime)))*sin((p.z-(iTime))/2.) - 1.75;
    return k;
}



vec3 getSkyColor(vec3 e){
    e.y = max(e.y, 0.0);
    float r = pow(1.0 - e.y, 2.0);
    float g = 1.0 - e.y;
    float b = 0.6 + (1.0 - e.y) * 0.4;
    return vec3(r, g, b);
}


float sdBox(vec3 p, vec3 b){
    vec3 d = abs(p) - b;
    return length(max(d, 0.)) + min(max(d.x, max(d.y, d.z)), 0.);
}
float sdPlane(vec3 p, float h){
    return abs(p.y-h);
}


vec2 opUnion(vec2 d1, vec2 d2){
    return (d1.x<d2.x) ? d1 : d2;
}

vec2 opSmoothUnionMix(float d1, float d2, float k){
    float h = max(k-abs(d1-d2), 0.0)/k;
    float m = h*h*h*0.5;
    float s = m*k*(1.0/3.0);
    return (d1<d2) ? vec2(d1-s, m) : vec2(d2-s, 1.0-m);
}


vec2 sceneDist(vec3 p){
    vec3 q;
    vec2 res = vec2(1e10, -1.); // 初期値: 距離を非常に大きく設定
    // 1. 地面（平面）
    res = opUnion(res,vec2(sdPlane(p,-3.5),0.));
    res = opUnion(res, vec2(sdPlane(p, wave(p)),2.));

    q = move(p.xzy, vec3(-3,-3,-2));
    if(max(abs(q.x), max(abs(q.y), abs(q.z))) < 5.0){
        q.yz *= rotation(0.5*sin(-iTime) + (PI*0.5));
        //res = opUnion(res, vec2(sdBox(move(q,vec3(0,wave(vec3(-3,-3,-1)),0)),vec3(2.0,0.25,2.))*0.75, 4.));
        float d1 = sdBox(move(q.xyz,vec3(0,wave(vec3(0,-3,0))+0.5+0.5,0)),vec3(2.0,0.125,1.5))*0.75;
        float d2 = sdPlane(p,wave(p));
        vec2 r = opSmoothUnionMix(d2,d1,1.25);
        r.y +=1.7;
        res = opUnion(res,r);
        res = opUnion(res, vec2(sdBox(move(q.xyz,vec3(0,wave(vec3(0,-3,0))-0.5+0.5,0)),vec3(0.2,1.,0.2))*0.75, 4.));
        res = opUnion(res, vec2(sdBox(move(q.xyz,vec3(0.75,wave(vec3(0,-3,0))-0.75+0.5, (wave(vec3(q.x,-3,0)) +1.75)*q.x)),vec3(0.75,0.50,0.1)), 5.));
    }

    return res;
}

vec3 getNormal(vec3 p){
  vec2 e = vec2(1.0, -1.0);
  vec2 ee = e * NORMAL_PRECISION;
  return normalize(
        e.xyy * sceneDist(p + ee.xyy).x +
        e.yxy * sceneDist(p + ee.yxy).x +
        e.yyx * sceneDist(p + ee.yyx).x +
        e.xxx * sceneDist(p + ee.xxx).x);
}





vec2 rayMarch(vec3 ro, vec3 rd, float exterior){
    vec2 res;
    float depth = MIN_RAY_DIST;
    for(int i = 0; i<MAX_RAY_STEPS; i++){
           vec3 p = ro + depth*rd;
           res = sceneDist(p);
           float d = res.x * exterior*0.5;
           if(d < RAY_PRECISION)
               break;
           depth += d;
           if(depth >= MAX_RAY_DIST)return vec2(MAX_RAY_DIST, -1.);
     }
     return vec2(depth,res.y);
}

vec3 rayDir(vec2 uv, vec3 forward, vec3 up, float focal){
    vec3 right = normalize(cross(forward, up));
    up = normalize(cross(right,forward));
    return normalize(focal * forward + uv.x * right + uv.y * up);
}

vec2 normalizeCoords(vec2 p){
    return (2.0*p-iResolution.xy)/iResolution.x;
}




float getAmbientOcclusion(vec3 ro, vec3 rd){
    float occ = 0.;
    float sca = 1.;
    for(int i = 0; i < 5; i++){
        float depth = 0.01 + 0.02 * float(i * i);
        float d = abs(sceneDist(ro + depth * rd).x);
        occ += max(depth - d, 0.) * sca;
        sca *= 0.75;
    }
    return clamp(1. - 2.5 * occ, 0., 1.);
}

float getShadow(vec3 ro, vec3 rd){
    float exposure = 1.;
    float depth = MIN_RAY_DIST;
    for(int i = 0; i < MAX_SHADOW_STEPS; i++){
        vec3 p = ro + depth * rd;
        float d = sceneDist(p).x;
        if (d < RAY_PRECISION) return 1. - SHADOW_DARKNESS;
        if (d < 0.015) i--;
        exposure = min(exposure, d / depth);
        depth += d;
        if(depth >= MAX_RAY_DIST) break;
    }
    exposure = clamp(exposure * SHADOW_HARDNESS, 0.1, 1.);
    return mix(1., exposure, SHADOW_DARKNESS);
}

vec3 refract2(vec3 I, vec3 N, float eta){
    float k = 1.0 - eta * eta * (1.0 - dot(N, I) * dot(N, I));
    if (k < 0.0) return reflect(I, N); // total internal reflection
    return eta * I - (eta * dot(N, I) + sqrt(k)) * N;
}


vec3 getColor(vec3 ro, vec3 rd, bool refl){
    vec3 totCol = vec3(0);
    float mixFactor = 1.;
    float exterior;

    vec3 lightPos = vec3(-1.,15.,-1.);

    for(int i = 0; i< MAX_REFLECTIONS; i++){
        exterior = sign(sceneDist(ro).x);
        vec2 res = rayMarch(ro, rd, exterior);
        float d = res.x;//衝突距離
        float m = res.y; //マテリアルのID
        vec3 p = ro + rd * d;//新たな点
        vec3 n = getNormal(p) * exterior;// 法線ベクトル


        vec3 col;  // オブジェクトの色
        float reflectivity = 0.;
        float refractivity = 0.;
        float refractionIndex = 0.;
        float specularFactor = 0.;
        float specularAlpha = 0.;
        float fresnelCoeff = 0.;


        if (m < -0.5) {  // 空
            col = getSkyColor(vec3(rd));
        } else if(m < 0.5){

            col = vec3(texture(iChannel1,vec2((fract(p.x/5.0)),(fract(p.z/5.0)) ) ));
            reflectivity = 0.25;
            refractivity = 0.;
            refractionIndex = 0.;
            specularFactor = 0.85;
            specularAlpha = 5.;
            fresnelCoeff = 0.;
        } else if (m < 2.5) {  //水

            col = vec3(0.19,0.74,0.85);
            reflectivity = 0.2;
            refractivity = 1.;
            refractionIndex = 1.05;
            specularFactor = 3.0;
            specularAlpha = 30.;
            fresnelCoeff = 0.2; 
        } else if(m < 4.5){  //いかだ
            //p.yz *= rotation( -(0.5*sin(-iTime) + (PI*0.5)) );
            col = vec3( texture(iChannel0,vec2( fract( sqrt( (p.z)*(p.z) +  ((p.y-wave(vec3(0,-3,0))) * (p.y-wave(vec3(0,-3,0)))) ) /5.0) , (fract((p.x/5.0))) ) ));
            reflectivity = 0.0;
            refractivity = 0.;
            refractionIndex = 0.;
            specularFactor = 0.85;
            specularAlpha = 3.;
            fresnelCoeff = 0.;

        }else if(m < 5.5){
            col = vec3(1,1,1);
            reflectivity = 0.0;
            refractivity = 0.;
            refractionIndex = 0.;
            specularFactor = 0.85;
            specularAlpha = 3.;
            fresnelCoeff = 0.;
        }

        if (m > -0.5) {
            vec3 lightDir = normalize(lightPos - p);  // 光の方向
            float occ = getAmbientOcclusion(p, n);   // 環境遮蔽
            float shadow = getShadow(p, lightDir);   // 影の計算
            float diffuse = dot(n, lightDir) * 0.5 + 0.5; // 拡散反射
            float specular = pow(clamp(dot(reflect(rd, n), lightDir), 0., 1.), specularAlpha); // スペキュラ反射

            col *= occ * shadow;  // 環境遮蔽と影を適用
            col *= diffuse;       // 拡散反射を適用
            col += specular * specularFactor; // スペキュラ反射を適用
        }

                // 4. 反射/屈折の計算
        if (reflectivity > 0. && (refractivity <= 0. || refl)) {
            totCol += col * (1. - reflectivity) * mixFactor;
            mixFactor *= reflectivity;
            ro = p;
            rd = reflect(rd, n);  // 反射方向にレイを更新
        } else if (refractivity > 0.) {
            totCol += col * (1. - refractivity) * mixFactor;
            mixFactor *= refractivity;
            ro = p;
            rd = refract2(rd, n, pow(refractionIndex, exterior));  // 屈折方向にレイを更新
        } else {
            totCol += col * mixFactor;  // 他の効果がない場合、最終色に追加
            break;
        }
    }

    return totCol;  // 最終的な色を返す
}





void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2 uv = normalizeCoords(fragCoord);
    vec3 ro = vec3(2.5,0.5,2.25);
    vec3 rd = rayDir(uv, normalize(-ro - vec3(0.,0.,0.)), vec3(0.,1.,0.), FOCAL_LENGTH);

    vec3 col = (getColor(ro, rd, true) + getColor(ro,rd,false)) * 0.5;

    fragColor = vec4(col,1.0);//vec4(getSkyColor(vec3(uv,-2.0)),1.0);
}
